public int findMinimumWeightWalk(int N, int[][] edges) {
    // Initialize the graph as an adjacency matrix with large values
    int[][] graph = new int[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i != j) {
                graph[i][j] = Integer.MAX_VALUE;
            }
        }
    }

    // Fill the graph with the given edges
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];
        graph[u][v] = Math.min(graph[u][v], w); // Use the minimum weight for multiple edges
    }

    // Use the Floyd-Warshall algorithm to find the shortest paths between all pairs of vertices
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (graph[i][k] != Integer.MAX_VALUE && graph[k][j] != Integer.MAX_VALUE) {
                    graph[i][j] = Math.min(graph[i][j], graph[i][k] + graph[k][j]);
                }
            }
        }
    }

    // Check if there is a walk that visits each vertex at least once
    int minWeight = Integer.MAX_VALUE;
    for (int i = 0; i < N; i++) {
        int totalWeight = 0;
        for (int j = 0; j < N; j++) {
            if (i != j) {
                if (graph[i][j] == Integer.MAX_VALUE) {
                    return -1; // If any vertex is unreachable, return -1
                }
                totalWeight += graph[i][j];
            }
        }
        minWeight = Math.min(minWeight, totalWeight);
    }

    return minWeight;
}

